function setupAnalyser(){try{if(!ctx){ctx=new(window.AudioContext||window.webkitAudioContext)();analyser=ctx.createAnalyser();analyser.fftSize=2048;source=ctx.createMediaElementSource(audio);source.connect(analyser);analyser.connect(ctx.destination);data=new Uint8Array(analyser.frequencyBinCount);waveData=new Uint8Array(analyser.fftSize)}if(ctx.state==='suspended')ctx.resume()}catch(e){}}
function trackKey(t){return String(t?.id||t?.track_id||t?.url||'').trim()}
function queueHasTrack(t){const key=trackKey(t);return !!key&&queue.some(x=>trackKey(x)===key)}
function addSearchTrack(t,button){if(button?.disabled)return;if(queueHasTrack(t)){if(button){button.disabled=true;button.textContent='✓'}searchMsg('Этот трек уже есть в очереди.','info');return}if(button){button.disabled=true;button.textContent='✓'}queue.push({...t,src:null});persistState();renderQueue();if(current>=0)preloadUpcoming();searchMsg('Добавлено в очередь: '+t.title,'success')}
function syncMediaSession(){if(!('mediaSession' in navigator))return;try{navigator.mediaSession.playbackState=audio.paused?'paused':'playing'}catch{}}
function updateMediaMetadata(t){if(!('mediaSession' in navigator)||!('MediaMetadata' in window))return;try{navigator.mediaSession.metadata=new MediaMetadata({title:t.title||'Pulse Vinyl',artist:t.artist||'',album:'Pulse Vinyl',artwork:t.cover?[{src:t.cover,sizes:'512x512',type:'image/jpeg'}]:[]})}catch{}}
if('mediaSession' in navigator){const actions={play:()=>{if(current>=0)audio.play().catch(()=>{});else if(queue.length)playIndex(0)},pause:()=>audio.pause(),previoustrack:()=>{if(current>0)playIndex(current-1)},nexttrack:()=>$('next').click(),seekto:e=>{if(Number.isFinite(e.seekTime))audio.currentTime=e.seekTime}};for(const [name,handler] of Object.entries(actions)){try{navigator.mediaSession.setActionHandler(name,handler)}catch{}}}
function persistState(){try{localStorage.setItem('pulseStateV11',JSON.stringify({queue:queue.map(({_loading,...t})=>({...t,src:null})),playlists,mode,waveHistory,recentHistory,queueView}))}catch(e){console.warn('[Pulse storage] Не удалось сохранить состояние',e)}}
function restoreState(){if(restoredState)return;restoredState=true;try{const s=JSON.parse(localStorage.getItem('pulseStateV11')||'null');if(!s)return;queue=Array.isArray(s.queue)?s.queue:[];playlists=Array.isArray(s.playlists)?s.playlists:[];mode=['collection','playlist','wave'].includes(s.mode)?s.mode:'collection';waveHistory=Array.isArray(s.waveHistory)?s.waveHistory:[];recentHistory=Array.isArray(s.recentHistory)?s.recentHistory:[];queueView=s.queueView==='recent'?'recent':'queue';renderPlaylistNavs();renderQueue()}catch(e){console.warn('[Pulse storage] Повреждённое сохранённое состояние',e);localStorage.removeItem('pulseStateV11')}}
function clearSavedState(){localStorage.removeItem('pulseStateV11');queue=[];playlists=[];waveHistory=[];recentHistory=[];current=-1;mode='collection';queueView='queue';renderPlaylistNavs();renderQueue()}
function renderQueue(){const el=$('queue');const recent=queueView==='recent';$('queueHeading').textContent=recent?'Недавно прослушанные':'Очередь воспроизведения';$('queueTabQueue')?.classList.toggle('active',!recent);$('queueTabRecent')?.classList.toggle('active',recent);const items=recent?recentHistory.slice(-100).reverse():queue.map((t,i)=>({...t,_queueIndex:i}));$('count').textContent=recent?String(items.length)+' ТРЕКОВ':String(queue.length)+' ТРЕКОВ';if(!items.length){el.className='queue-empty';el.textContent=recent?'История прослушивания пока пуста.':'Твоя очередь пока пуста.';return}el.className='';el.innerHTML='';items.forEach((t,i)=>{const idx=t._queueIndex;const row=document.createElement('div');row.className='queue-item '+(!recent&&idx===current?'active':'');row.innerHTML='<div class="queue-index">'+(!recent&&idx===current?'▶':String(i+1).padStart(2,'0'))+'</div><div class="queue-meta"><div class="queue-title"></div><div class="queue-artist"></div></div>'+(recent?'':'<button class="queue-remove" title="Удалить">×</button>');row.querySelector('.queue-title').textContent=t.title;row.querySelector('.queue-artist').textContent=t.artist;row.tabIndex=0;row.setAttribute('role','button');row.onclick=()=>recent?playWaveHistoryTrack(t):playIndex(idx);if(!recent)row.querySelector('button').onclick=e=>{e.stopPropagation();queue.splice(idx,1);if(idx===current){audio.pause();current=-1;resetTrack()}else if(idx<current)current--;persistState();renderQueue()};el.appendChild(row)})}
function playWaveHistoryTrack(t){const upcoming=current>=0?queue.slice(current+1):queue.slice();queue=[{...t},...upcoming];current=-1;persistState();audio.pause();renderQueue();playIndex(0)}
function resetTrack(){$('trackTitle').textContent='Ничего не играет';$('trackArtist').textContent='Добавь трек через поиск или ссылку';setRecordArc('labelTitle','YOUR NEXT TRACK',365);setRecordArc('labelArtist','PULSAR',365);setRecordCover(null);$('record').classList.remove('spinning');$('tonearm').classList.remove('playing');$('play').textContent='▶'}
async function reactTrack(action){if(current<0||!queue[current])return;const t=queue[current];try{const r=await fetch('/api/track-reaction',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({track_id:t.track_id||String(t.id||'').split(':')[0],action})});const d=await r.json();if(!r.ok)throw Error(d.error||'Не удалось изменить оценку');$('likeTrack').classList.toggle('selected',action==='like');$('dislikeTrack').classList.toggle('selected',action==='dislike');msg(action==='like'?'Лайк отправлен в Яндекс Музыку.':'Дизлайк отправлен в Яндекс Музыку.','success')}catch(e){msg(e.message,'error')}}
async function fetchJson(url){const r=await fetch(url);const d=await r.json();if(!r.ok)throw Error(d.error||'Ошибка сервера');return d}
async function downloadTrack(t, quiet=false){if(t.src)return t;if(t._loading)return t._loading;t._loading=(async()=>{const started=performance.now();if(!quiet)msg('Загружаю аудио: '+t.title+'…');const d=await fetchJson('/api/track?url='+encodeURIComponent(t.url));let delay=350;for(let i=0;i<240;i++){await new Promise(r=>setTimeout(r,delay));const st=await fetchJson('/api/track-status?id='+encodeURIComponent(d.job_id));if(st.status==='done'){Object.assign(t,st.result);console.info('[Pulse timing] track ready', {title:t.title,client_wait_ms:Math.round(performance.now()-started),...st.timings});return t}if(st.status==='error')throw Error(st.error||'Не удалось получить аудио');if(i%4===0&&!quiet)msg(st.progress||'Готовлю аудио…');delay=Math.min(1000,delay+100)}throw Error('Загрузка заняла слишком много времени. Попробуй ещё раз.')})();try{return await t._loading}finally{delete t._loading}}
function preloadUpcoming(){let count=0;for(let i=current+1;i<queue.length&&count<2;i++){const next=queue[i];if(!next.src&&!preloading.has(next)){count++;preloading.add(next);downloadTrack(next,true).catch(()=>{}).finally(()=>preloading.delete(next))}}}
function setRecordArc(id,value,maxLength=365){const el=$(id);if(!el)return;const text=String(value||'').trim();el.textContent=text;const length=text.length;const size=length>34?12:length>26?14:length>18?16:18;el.setAttribute('font-size',String(size));el.setAttribute('textLength',String(Math.min(maxLength,Math.max(80,length*size*.58))));el.setAttribute('lengthAdjust','spacingAndGlyphs')}
function setRecordCover(track){const img=$('recordCover');if(!img)return;const cover=track?.cover||track?.cover_url||'';if(cover){img.onerror=()=>{img.hidden=true;img.removeAttribute('src')};img.src=cover;img.hidden=false}else{img.hidden=true;img.removeAttribute('src')}}
async function playIndex(i){if(i<0||i>=queue.length)return;const previous=current;const t=queue[i];if(mode==='wave'&&(previous!==i)&&(waveHistory.length===0||waveHistory[waveHistory.length-1].id!==t.id)){if(previous>=0&&queue[previous])waveHistory.push({...queue[previous]})}current=i;recentHistory=recentHistory.filter(x=>x.id!==t.id);recentHistory.push({...t,src:null});if(recentHistory.length>100)recentHistory=recentHistory.slice(-100);persistState();renderQueue();updateMediaMetadata(t);$('trackTitle').textContent=t.title;$('trackArtist').textContent=t.artist;setRecordArc('labelTitle',t.title,365);setRecordArc('labelArtist',t.artist,365);setRecordCover(t);$('statusText').textContent='LOADING';$('tonearm').classList.remove('playing');try{await downloadTrack(t);audio.src=t.src;audio.load();setupAnalyser();if(ctx?.state==='suspended')await ctx.resume();await audio.play();$('record').classList.add('spinning');requestAnimationFrame(()=>$('tonearm').classList.add('playing'));$('play').textContent='Ⅱ';$('statusText').textContent='PLAYING';msg('Воспроизводится: '+t.title,'success');renderQueue();preloadUpcoming()}catch(e){$('statusText').textContent='READY';$('record').classList.remove('spinning');$('tonearm').classList.remove('playing');msg('Не удалось воспроизвести трек: '+e.message,'error')}}
async function addByUrl(){const url=$('url').value.trim();if(!url)return msg('Вставь ссылку на трек или плейлист.','error');if(adding)return;adding=true;$('add').disabled=true;try{if(/\/multivibe\//i.test(url)){throw Error('Для твоей личной «Моей волны» ссылка не нужна — открой «Моя волна» в боковой панели. Общую волну по ссылке эта версия пока не импортирует.')}if(/\/playlists\//i.test(url)){msg('Загружаю треки плейлиста…');const d=await fetchJson('/api/playlist?url='+encodeURIComponent(url));const pl={id:d.id,title:d.title,tracks:d.tracks};playlists=playlists.filter(x=>x.id!==pl.id);playlists.push(pl);persistState();renderPlaylistNavs();$('url').value='';$('linkPopover').hidden=true;msg(`Плейлист «${pl.title}» добавлен. Выбери его на боковой панели.`,'success');return}msg('Получаю название и исполнителя…');const t=await fetchJson('/api/resolve?url='+encodeURIComponent(url));queue.push(t);persistState();$('url').value='';renderQueue();msg('Добавлено в очередь: '+t.title,'success');$('linkPopover').hidden=true;if(current<0)await playIndex(0);else preloadUpcoming()}catch(e){msg(e.message,'error')}finally{adding=false;$('add').disabled=false}}
function setNavActive(id){document.querySelectorAll('.nav,.playlist-nav').forEach(x=>x.classList.remove('active'));$(id)?.classList.add('active')}
function renderPlaylistNavs(){const host=$('playlistNavs');host.innerHTML='';playlists.forEach(pl=>{const b=document.createElement('button');b.className='playlist-nav'+(mode==='playlist'&&queue[0]?queue[0]._playlistId===pl.id?' active':'':'');b.id='playlist-'+pl.id;b.textContent='♫　'+pl.title;b.title=pl.title;b.onclick=()=>{mode='playlist';queue=pl.tracks.map(t=>({...t,src:null,_playlistId:pl.id}));current=-1;persistState();audio.pause();setNavActive(b.id);renderQueue();if(queue.length)playIndex(0)};host.appendChild(b)})}
let waveUpcoming=[];
async function fetchMoreWave(){
  if(waveLoading)return false;
  waveLoading=true;
  try{
   const played=[...waveHistory,...(current>=0&&queue[current]?[queue[current]]:[])];
   const ids=[...new Set(played.map(t=>String(t.track_id||String(t.id||'').split(':')[0])).filter(id=>/^\d+$/.test(id)))];
   const d=await fetchJson('/api/my-wave?queue='+encodeURIComponent(ids.join(',')));
   const seen=new Set([...waveHistory,...queue,...waveUpcoming].map(t=>t.id));
   const fresh=(d.tracks||[]).filter(t=>!seen.has(t.id));
   if(!fresh.length){msg('Яндекс пока не вернул новые треки для Моей волны. Попробуй ещё раз чуть позже.','error');return false}
   waveUpcoming.push(...fresh);waveBatchId=d.batch_id||waveBatchId;return true;
  }finally{waveLoading=false}
}
async function advanceWave(){
  if(mode!=='wave')return false;
  if(current>=0&&queue[current]){waveHistory.push({...queue[current],src:null});if(waveHistory.length>100)waveHistory=waveHistory.slice(-100)}
  if(!waveUpcoming.length){const loaded=await fetchMoreWave();if(!loaded)return false}
  const next=waveUpcoming.shift();queue=[next];current=-1;persistState();renderQueue();await playIndex(0);return true;
}
async function openWave(){setNavActive('waveNav');mode='wave';waveHistory=[];waveUpcoming=[];waveLoading=true;queue=[];current=-1;persistState();audio.pause();renderQueue();msg('Подключаю Мою волну…');try{const d=await fetchJson('/api/my-wave');waveBatchId=d.batch_id;const tracks=d.tracks||[];if(!tracks.length)throw Error('Яндекс не вернул треки Моей волны.');queue=[tracks[0]];waveUpcoming=tracks.slice(1);renderQueue();msg('Моя волна готова','success');await playIndex(0)}catch(e){msg(e.message,'error')}finally{waveLoading=false}}
