async function search(){const searchStarted=performance.now();const q=$('searchInput').value.trim();$('searchDropdown').hidden=false;if(q.length<2){searchMsg('Введи хотя бы 2 символа.');return}const btn=$('searchBtn');btn.disabled=true;$('searchResults').innerHTML='';searchMsg('Ищу в Яндекс Музыке…');try{const d=await fetchJson('/api/search?q='+encodeURIComponent(q));console.info('[Pulse timing] search', {client_total_ms:Math.round(performance.now()-searchStarted),...d.timings});if(!d.results.length){searchMsg('Ничего не найдено. Попробуй другой запрос.');return}searchMsg(`Найдено: ${d.results.length}.`,'success');const list=$('searchResults');d.results.forEach(t=>{const row=document.createElement('div');row.className='search-result';const art=document.createElement('div');art.className='result-cover';art.textContent='♫';if(t.cover){const img=document.createElement('img');img.src=t.cover;img.loading='lazy';img.onerror=()=>img.remove();art.textContent='';art.appendChild(img)}const meta=document.createElement('div');meta.className='result-meta';const title=document.createElement('div');title.className='result-title';title.textContent=t.title;const artist=document.createElement('div');artist.className='result-artist';artist.textContent=t.artist;meta.append(title,artist);const actions=document.createElement('div');actions.className='result-actions';const play=document.createElement('button');play.title='Слушать';play.textContent='▶';play.onclick=()=>{queue.push({...t,src:null});persistState();renderQueue();if(current>=0&&queue.length-1<=current+2)preloadUpcoming();playIndex(queue.length-1)};const plus=document.createElement('button');plus.title='Добавить в очередь';plus.textContent=queueHasTrack(t)?'✓':'+';plus.disabled=queueHasTrack(t);plus.onclick=()=>addSearchTrack(t,plus);actions.append(play,plus);row.append(art,meta,actions);list.appendChild(row)})}catch(e){searchMsg(e.message,'error')}finally{btn.disabled=false}}
$('searchBtn').onclick=search;$('searchInput').addEventListener('focus',()=>{if($('searchResults').children.length||$('searchMessage').textContent.trim())$('searchDropdown').hidden=false});$('searchInput').addEventListener('keydown',e=>{if(e.key==='Enter')search();if(e.key==='Escape')$('searchDropdown').hidden=true});$('searchInput').addEventListener('input',()=>{clearTimeout(searchTimer);if($('searchInput').value.trim().length>=3)searchTimer=setTimeout(search,500)});
$('play').onclick=()=>{if(!queue.length)return msg('Сначала добавь трек.');if(audio.paused){if(current<0)playIndex(0);else{setupAnalyser();audio.play().then(()=>{$('record').classList.add('spinning');$('tonearm').classList.add('playing');$('play').textContent='Ⅱ';$('statusText').textContent='PLAYING'}).catch(e=>msg(e.message,'error'))}}else audio.pause()};
$('likeTrack').onclick=()=>reactTrack('like');$('dislikeTrack').onclick=()=>reactTrack('dislike');$('prev').onclick=()=>playIndex(Math.max(0,current-1));$('next').onclick=async()=>{if(mode==='wave'){try{msg('Запрашиваю следующий трек Моей волны…');await advanceWave()}catch(e){msg('Не удалось продолжить Мою волну: '+e.message,'error')}return}if(current+1<queue.length){playIndex(current+1);return}msg('Это последний трек в очереди.')};$('stop').onclick=()=>{audio.pause();audio.currentTime=0;$('record').classList.remove('spinning');$('tonearm').classList.remove('playing');$('play').textContent='▶';$('statusText').textContent='READY'};
audio.onplay=()=>{syncMediaSession();$('record').classList.add('spinning');$('tonearm').classList.add('playing');$('play').textContent='Ⅱ';$('statusText').textContent='PLAYING'};audio.onpause=()=>{syncMediaSession();if(!audio.ended){$('record').classList.remove('spinning');$('tonearm').classList.remove('playing');$('play').textContent='▶';if($('statusText').textContent==='PLAYING')$('statusText').textContent='PAUSED'}};
audio.onended=async()=>{if(mode==='wave'){try{$('statusText').textContent='WAVE LOADING';await advanceWave()}catch(e){$('statusText').textContent='WAVE WAITING';msg('Не удалось продолжить Мою волну: '+e.message,'error')}}else if(current+1<queue.length){$('tonearm').classList.remove('playing');playIndex(current+1)}else{$('record').classList.remove('spinning');$('tonearm').classList.remove('playing');$('play').textContent='▶';$('statusText').textContent='SESSION READY'}};
audio.ontimeupdate=()=>{$('elapsed').textContent=fmt(audio.currentTime*1000);$('duration').textContent=fmt(audio.duration*1000);if(audio.duration)$('seek').value=audio.currentTime/audio.duration*1000};$('seek').oninput=()=>{if(audio.duration)audio.currentTime=audio.duration*$('seek').value/1000};$('volume').oninput=()=>{audio.volume=+$('volume').value;$('volumeText').textContent=Math.round(audio.volume*100)+'%'};audio.volume=.8;
$('showSidebar').onclick=()=>{document.body.classList.toggle('collapsed');const hidden=document.body.classList.contains('collapsed');$('showSidebar').textContent='☰';$('showSidebar').title=hidden?'Показать боковую панель':'Скрыть боковую панель';$('showSidebar').setAttribute('aria-label',$('showSidebar').title)};$('linkToggle').onclick=()=>{$('linkPopover').hidden=!$('linkPopover').hidden;if(!$('linkPopover').hidden)$('url').focus()};document.addEventListener('click',e=>{if(!$('linkPopover').contains(e.target)&&!$('linkToggle').contains(e.target))$('linkPopover').hidden=true;if(!$('headerSearchPlaceholder') && !$('searchInput').closest('.header-search').contains(e.target))$('searchDropdown').hidden=true});$('loginBtn').onclick=async()=>{const status=await fetch('/api/status').then(r=>r.json()).catch(()=>({auth:'idle'}));if(status.auth==='ready'){if(confirm('Сменить пользователя Яндекс Музыки? Текущая авторизация в Pulse Vinyl будет сброшена.')){await fetch('/api/logout',{method:'POST'});clearSavedState();window.open('https://passport.yandex.ru/auth/list?retpath='+encodeURIComponent('https://music.yandex.ru/'),'_blank','noopener');$('authModal').hidden=false;document.body.classList.add('modal-open');$('authHelpModal').textContent='Выбери нужный аккаунт в открывшейся вкладке, затем получи новый код здесь.';$('requestCodeModal').hidden=false;$('requestCodeModal').textContent='Получить код для другого аккаунта';$('authStatus').textContent='Требуется авторизация';$('loginBtn').textContent='↗　Войти в Яндекс'}return}$('authModal').hidden=false;authModalDismissed=false;document.body.classList.add('modal-open');checkAuth()};$('requestCodeModal').onclick=async()=>{authModalDismissed=false;const pipPromise=openAuthPip();authPageWindow=window.open('about:blank','pulseYandexDevice');$('requestCodeModal').disabled=true;$('authCodeWrapModal').hidden=true;$('authHelpModal').textContent='Запрашиваю одноразовый код…';try{const r=await fetch('/api/login',{method:'POST',cache:'no-store'});if(!r.ok)throw Error('HTTP '+r.status);for(let i=0;i<40;i++){await checkAuth();if(!$('authCodeWrapModal').hidden||$('authHelpModal').textContent.startsWith('Ошибка:'))break;await new Promise(resolve=>setTimeout(resolve,500))}if(!$('authCodeWrapModal').hidden){const pip=await pipPromise;updateAuthPip($('authCodeModal').textContent,$('authLinkModal').href);if(authPageWindow&&!authPageWindow.closed)authPageWindow.location.href=$('authLinkModal').href;$('authModal').hidden=true;document.body.classList.remove('modal-open')}}catch(e){$('authHelpModal').textContent='Не удалось открыть плавающее окно или запросить код: '+e.message;if(authPopup&&!authPopup.closed)authPopup.close();authPopup=null;if(authPageWindow&&!authPageWindow.closed)authPageWindow.close();authPageWindow=null}finally{$('requestCodeModal').disabled=false}};$('closeAuthModal').onclick=async()=>{authModalDismissed=true;if(authPollTimer)clearTimeout(authPollTimer);authPollTimer=null;$('authModal').hidden=true;document.body.classList.remove('modal-open');if(authPopup&&!authPopup.closed)authPopup.close();authPopup=null;if(authPageWindow&&!authPageWindow.closed)authPageWindow.close();authPageWindow=null;try{await fetch('/api/logout',{method:'POST',cache:'no-store'})}catch{}$('authHelpModal').textContent='Авторизация отменена. Нажми «Войти в Яндекс», чтобы начать заново.';$('requestCodeModal').hidden=false;$('requestCodeModal').textContent='Получить код'};$('copyCodeModal').onclick=async()=>{try{await navigator.clipboard.writeText($('authCodeModal').textContent);$('copyCodeModal').textContent='СКОПИРОВАНО'}catch{$('authHelpModal').textContent='Скопируй код вручную.'}};$('copyCode').onclick=async()=>{try{await navigator.clipboard.writeText($('authCode').textContent);$('copyCode').textContent='СКОПИРОВАНО';setTimeout(()=>$('copyCode').textContent='КОПИРОВАТЬ',1600)}catch{$('authHelp').textContent='Не удалось скопировать. Выдели код и скопируй вручную.'}};
let authPollTimer=null,authCheckBusy=false,authPopup=null,authPageWindow=null,authModalDismissed=false;
function scheduleAuthPoll(){if(authPollTimer)clearTimeout(authPollTimer);authPollTimer=setTimeout(()=>checkAuth(),2500)}
function openAuthPip(){if(!window.documentPictureInPicture?.requestWindow)return Promise.reject(new Error('Document Picture-in-Picture не поддерживается. Используй актуальный Chrome или Edge.'));return window.documentPictureInPicture.requestWindow({width:340,height:230}).then(w=>{authPopup=w;const d=w.document;d.title='Pulse Vinyl — авторизация';d.body.innerHTML=`<style>*{box-sizing:border-box}body{margin:0;padding:18px;background:#f7f8f3;color:#252820;font:13px Arial,sans-serif}header{font-size:10px;letter-spacing:2px;font-weight:700;margin-bottom:14px}.label{font-size:10px;color:#777b70;letter-spacing:1px}.code{font-size:29px;font-weight:800;letter-spacing:2px;margin:9px 0 13px;color:#a6d900}.actions{display:flex;gap:8px}button,a{border:0;border-radius:9px;padding:10px 12px;font-weight:700;text-decoration:none;font-size:10px;cursor:pointer}button{background:#c6ff00;color:#20231b}a{background:#e8ebdf;color:#303329}#pipStatus{font-size:10px;color:#777b70;margin-top:12px}</style><header>PULSE VINYL</header><div class="label">ТВОЙ КОД АВТОРИЗАЦИИ</div><div class="code" id="pipCode">Получаем…</div><div class="actions"><button id="pipCopy">КОПИРОВАТЬ</button><a id="pipLink" href="https://ya.ru/device" target="_blank" rel="noreferrer">ОТКРЫТЬ ЯНДЕКС ↗</a></div><div id="pipStatus">Получаем одноразовый код…</div>`;d.getElementById('pipCopy').onclick=async()=>{try{await d.defaultView.navigator.clipboard.writeText(d.getElementById('pipCode').textContent);d.getElementById('pipStatus').textContent='Код скопирован'}catch{d.getElementById('pipStatus').textContent='Выдели код и скопируй вручную'}};w.addEventListener('pagehide',()=>{if(authPopup===w)authPopup=null});return w})}
function updateAuthPip(code,url){if(!authPopup||authPopup.closed)return;const d=authPopup.document;d.getElementById('pipCode').textContent=code||'…';d.getElementById('pipLink').href=url||'https://ya.ru/device';d.getElementById('pipStatus').textContent=code?'Открой Яндекс и введи этот код':'Получаем одноразовый код…'}
async function checkAuth(){if(authCheckBusy)return;authCheckBusy=true;try{const r=await fetch('/api/status',{cache:'no-store'}),s=await r.json();const ready=s.auth==='ready';$('authStatus').textContent=ready?'● Авторизовано':s.auth==='pending'?'Ожидаю подтверждения…':s.auth==='error'?'Ошибка авторизации':'Не авторизовано';$('loginBtn').textContent=ready?'⇄　Сменить пользователя':'↗　Войти в Яндекс';if(ready){restoreState();setNavActive(mode==='wave'?'waveNav':'collectionNav');if(authPollTimer)clearTimeout(authPollTimer);authPollTimer=null;if(authPopup&&!authPopup.closed)authPopup.close();authPopup=null;if(authPageWindow&&!authPageWindow.closed)authPageWindow.close();authPageWindow=null;$('authModal').hidden=true;document.body.classList.remove('modal-open');$('statusText').textContent='ВЫ АВТОРИЗОВАНЫ — ЯНДЕКС.МУЗЫКА';return}if(s.auth==='pending'){scheduleAuthPoll();if(!authModalDismissed){$('authModal').hidden=false;document.body.classList.add('modal-open')};$('authHelpModal').textContent=s.auth_code?'Введи этот код на странице Яндекса.':'Подготавливаю код авторизации…';if(s.auth_url&&s.auth_code){$('authCodeWrapModal').hidden=false;$('authCodeModal').textContent=s.auth_code;$('authLinkModal').href=s.auth_url;$('requestCodeModal').hidden=true}else{$('authCodeWrapModal').hidden=true;$('requestCodeModal').hidden=false}}else if(s.auth==='error'){authModalDismissed=false;if(authPollTimer)clearTimeout(authPollTimer);authPollTimer=null;$('authModal').hidden=false;$('authHelpModal').textContent='Ошибка: '+s.auth_error;$('requestCodeModal').hidden=false;$('requestCodeModal').textContent='Попробовать снова'}else {if(authPollTimer)clearTimeout(authPollTimer);authPollTimer=null;if(s.auth==='idle')clearSavedState()}}catch{}finally{authCheckBusy=false}}

function updateVizUI(){const v=vizModes.find(x=>x.id===previewViz)||vizModes[0];document.body.classList.toggle('viz-mode',previewViz!=='vinyl');document.body.classList.toggle('engine-viz',previewViz.startsWith('butterchurn-')||previewViz.startsWith('noisemaker-'));document.body.classList.toggle('noisemaker-mode',previewViz.startsWith('noisemaker-'));if(window.PulsarEngines)window.PulsarEngines.select(previewViz);$('vizTitle').textContent=v.name;$('vizPreviewName').textContent=v.name;$('vizPreviewDesc').textContent=v.desc;$('vizTitleChip').hidden=previewViz==='vinyl';$('changeViz').textContent=choosingViz?'Закрыть выбор':'✦　Сменить визуализатор';$('vizPicker').hidden=!choosingViz;$('vizPrev').hidden=!choosingViz;$('vizNext').hidden=!choosingViz;$('chooseViz').textContent=previewViz===selectedViz?'Выбрать':'Выбрать этот визуализатор';$('vizHint').textContent=choosingViz?'Листай стрелками и нажми «Выбрать»':'Активный режим: '+v.name;}
function stepViz(delta){let i=vizModes.findIndex(v=>v.id===previewViz);i=(i+delta+vizModes.length)%vizModes.length;previewViz=vizModes[i].id;updateVizUI()}
$('changeViz').onclick=()=>{if(!choosingViz){previewViz=selectedViz;choosingViz=true}else{choosingViz=false;previewViz=selectedViz}updateVizUI()};$('vizPrev').onclick=()=>stepViz(-1);$('vizNext').onclick=()=>stepViz(1);$('chooseViz').onclick=()=>{selectedViz=previewViz;localStorage.setItem('pulsarViz',selectedViz);choosingViz=false;updateVizUI();if(selectedViz.startsWith('butterchurn-')){setupAnalyser();const stage=$('engineViz').parentElement.getBoundingClientRect();window.PulsarEngines?.prepare?.({ctx,source,analyser,width:stage.width,height:stage.height},selectedViz)}msg('Визуализатор «'+currentViz().name+'» выбран.','success')};
window.addEventListener('keydown',e=>{if(!choosingViz)return;if(e.key==='ArrowLeft')stepViz(-1);if(e.key==='ArrowRight')stepViz(1);if(e.key==='Escape'){choosingViz=false;previewViz=selectedViz;updateVizUI()}});window.addEventListener('resize',()=>{const c=$('viz');if(c){c.width=0;c.height=0}});updateVizUI();draw();

